bounded_host_request.command:
set -euo pipefail
origin="$(git remote get-url origin)"
case "$origin" in *seigo-gace/create-videobot*) ;; *) echo VIDEO_SOURCE_ORIGIN_MISMATCH; exit 51;; esac
test -f src/telegram/creatorWizard.mjs || { echo VIDEO_SOURCE_NOT_FOUND; exit 52; }
git fetch --no-tags origin feat/assistant-ai-and-sales-core
test "$(git rev-parse FETCH_HEAD)" = "e60b2076fa5f87a58e7c7b1e3ee3706b06b1e552" || { echo VIDEO_HEAD_MISMATCH; exit 53; }
echo VIDEO_FETCH_HEAD=PASS
echo VIDEO_CURRENT_HEAD="$(git rev-parse HEAD)"
test -z "$(git status --porcelain --untracked-files=no)" || { echo VIDEO_CHECKOUT_DIRTY; exit 54; }
echo VIDEO_CHECKOUT_CLEAN=PASS
test -f deploy/compose.videobot.poll.yaml || { echo VIDEO_POLL_COMPOSE_MISSING; exit 55; }
echo VIDEO_COMPOSE_PRESENT=PASS
